  // Identificadores utilizados pelos testes de geometria / caminhada.
  const STAIR_STEP_Z=[-1.30,-.78,-.26,.26,.78,1.30];
  const STAIR_STEP_TOP=[.55,1.05,1.55,2.05,2.55,3.05];

  function pieceMat(kind){return kind==='rock'?rockMat:kind==='branch'?twigMat:vineMat;}
  function pieceMesh(kind,len){
    if(kind==='rock'){const m=new T.Mesh(new T.BoxGeometry(1.08,.22,1.08),rockMat);m.castShadow=!mobile;m.receiveShadow=true;return m;}
    if(kind==='branch'||kind==='vine'){
      const m=new T.Mesh(new T.CylinderGeometry(kind==='vine'?.027:.055,kind==='vine'?.027:.08,len,6),pieceMat(kind));m.castShadow=!mobile;return m;
    }
    return plankMesh(len);
  }
  function ghostPiece(part){
    let m=part.kind==='log'?logGhostMesh(part.len,part.radius||WALL_LOG_RADIUS,ghostGood):part.kind==='plank'?plankGhostMesh(part.len,ghostGood):pieceMesh(part.kind,part.len);
    m.material=ghostGood;m.castShadow=false;m.receiveShadow=false;return fitMesh(m,part);
  }


  // V222: catálogo usa a mesma montagem, inventário e cena do jogo original.
  const board=(x,y,z,len=GRID,q=null,width=.56,thickness=.14)=>({...slot('plank',x,y,z,len,q),width,thickness});
  const stone=(x,y,z,w,h,d)=>({...slot('rock',x,y,z),size:[w,h,d]});
  const log=(x,y,z,len,q=null,r=.16)=>({...slot('log',x,y,z,len,q),radius:r});
  const along=(a,b,kind='log',r=.13)=>{const v=new T.Vector3(...b).sub(new T.Vector3(...a));return {...slot(kind,(a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2,v.length(),new T.Quaternion().setFromUnitVectors(kind==='plank'?Z:UP,v.clone().normalize())),radius:r};};
  function define(id,name,category,foot,height,slots,extra={}){
    const counts={};slots.forEach(p=>counts[p.kind]=(counts[p.kind]||0)+1);
    const names={plank:'tábuas',log:'troncos',rock:'pedras',branch:'galhos',vine:'cipós'};
    DEF[id]={id,name,category,foot,height,slots,total:slots.length,resource:slots[0]?.kind,
      desc:Object.entries(counts).map(([k,n])=>`${n} ${names[k]}`).join(' + ')+' • montagem por peça',...extra};
  }
  const deck=(w,d,y=.07)=>Array.from({length:Math.ceil(w/.54)},(_,i)=>board(-w/2+(i+.5)*w/Math.ceil(w/.54),y,0,d,null,w/Math.ceil(w/.54)+.012));
  define('floor_half','Meio piso de tábuas','floor',[GRID,GRID/2],.14,deck(GRID,GRID/2));
