  const leaf=(w,h)=>Array.from({length:Math.ceil(w/.5)},(_,i)=>board((i+.5)*w/Math.ceil(w/.5),h/2,0,h,qBoardVertical,w/Math.ceil(w/.5)+.01));
  define('door_wood','Porta de madeira','door',[1.4,.14],2.64,leaf(1.4,2.64).map(p=>({...p,pos:p.pos.clone().add(new T.Vector3(-.7,0,0))})),{hinged:true});
