          const h=top-roofMin(selected);
          if(cat==='pillar')for(const ix of [-1,1])for(const iz of [-1,1])pose(p.x+ix*selected.foot[0]/2,p.z+iz*selected.foot[1]/2,h,userYaw,site,{roofSupport:site});
          else for(const sign of [-1,1])pose(p.x+sign*Math.sin(a)*selected.foot[1]/2,p.z+sign*Math.cos(a)*selected.foot[1]/2,h,a,site,{roofSupport:site});
