    manager.querySelector('h3').textContent=site.def.name;manager.querySelector('.cm-info').textContent=`Montagem ${site.count}/${site.def.total} • Integridade ${Math.round(site.hp??100)}% • Material: ${structureResistance(site).name} • Resistência: ${Math.round(100/structureResistance(site).mult)}%`;
