    const addRow=(item,cmd,label)=>{const row=document.createElement('div');row.className='cm-row';const span=document.createElement('span');span.textContent=item.name+' × '+item.quantity;const b=document.createElement('button');b.textContent=label;b.onclick=()=>manageSite(cmd,site,item.id);row.append(span,b);el.appendChild(row);};
