    let best=null,score=.86;cam.getWorldDirection(dir);
    for(const s of sites){if(Math.hypot(s.root.position.x-player.x,s.root.position.z-player.z)>4.4)continue;tmp.copy(s.root.position);tmp.y+=Math.min(1,s.def.height/2);tmp.sub(cam.position);if(tmp.length()<.1)continue;const dot=dir.dot(tmp.normalize());if(dot>score){score=dot;best=s;}}
    managedSite=best;manageBtn.style.display=best?'block':'none';if(best)manageBtn.textContent=best.def.name+' · Gerenciar'+(best.def.hinged?' · T abrir/fechar':'');
